block result;
if (n == 0) {
    return result;
}

const auto aligned_length = round_to_alignment(alignment, n);
if (aligned_length > static_cast<size_t>(data + max_size - p)) {
    return result;
}

p = static_cast<char*>(std::align(alignment, n, p, sizeof(char*)));
if (!p) {
    result.reset();
    return result;
}

if (aligned_length > max_size - (p - data)) {
    result.reset();
    return result;
}

size_t* space_left = reinterpret_cast<size_t*>(data + max_size - p);
if (*space_left < aligned_length) {
    result.reset();
    return result;
}

p += aligned_length;
result.ptr = p;
result.length = aligned_length;
p += aligned_length;

return result;

